import{_ as s,a8 as r,o as i,c as p,au as m,a as c,a3 as t,K as o,L as a}from"./chunks/framework.ChlCBTXf.js";import"./chunks/theme.BFqyJFsI.js";const N=JSON.parse('{"title":"Codex 的记忆分两层，但第一层根本不是记忆","description":"","frontmatter":{"title":"Codex 的记忆分两层，但第一层根本不是记忆","abstract":"Codex 的 AGENTS.md 是指令链而非记忆，Memories 才是自动沉淀层。它真正的设计意图不是\\"记住更多\\"，而是用空闲门控、额度门控和 30 天剪枝，尽量少记。","created":"2026-11-09T00:00:00.000Z","updated":"2026-11-10T00:00:00.000Z","type":"调研","tags":["AI","Codex","Agent","记忆系统"],"category":["🧩 AI框架与Agent","AI 应用核心范式"]},"headers":[],"relativePath":"vault/Knowledge/AI/Codex 的记忆系统.md","filePath":"vault/Knowledge/AI/Codex 的记忆系统.md","lastUpdated":1794320166000}'),g={name:"vault/Knowledge/AI/Codex 的记忆系统.md"};function u(h,e,b,_,x,C){const d=r("VPNolebaseInlineLinkPreview"),n=r("NolebaseGitContributors"),l=r("NolebaseGitChangelog");return i(),p("div",null,[e[7]||(e[7]=m('<h1 id="codex-的记忆分两层-但第一层根本不是记忆" tabindex="-1">Codex 的记忆分两层，但第一层根本不是记忆 <a class="header-anchor" href="#codex-的记忆分两层-但第一层根本不是记忆" aria-label="Permalink to “Codex 的记忆分两层，但第一层根本不是记忆”">​</a></h1><p>把 Codex 的 <code>AGENTS.md</code> 和 Memories 说成&quot;两层记忆&quot;，容易让人以为它们是一回事，只是层级不同。实际不是。</p><p><strong><code>AGENTS.md</code> 是指令链，由人写、进版本控制；Memories 是自动沉淀层，由后台模型写。</strong> 两者的生命周期、可信度、失效方式完全不同。混为一谈，会导致你在该用规则的地方用记忆，或者反过来。</p><h2 id="一、第一层-agents-md-是启动时拼出来的指令" tabindex="-1">一、第一层：AGENTS.md 是启动时拼出来的指令 <a class="header-anchor" href="#一、第一层-agents-md-是启动时拼出来的指令" aria-label="Permalink to “一、第一层：AGENTS.md 是启动时拼出来的指令”">​</a></h2><p>发现顺序是固定的：全局目录取一个文件（<code>AGENTS.override.md</code> 优先），然后从项目根逐级走到当前工作目录，每个目录最多取一个文件。拼接顺序是根在前、cwd 在后。</p><p><strong>越靠近 cwd 的规则，实际优先级越高</strong>——不是因为官方规定了优先级，而是因为它出现在拼接结果的后面。这是个容易忽略的隐式规则。</p><p>兼容性方面，<code>project_doc_fallback_filenames</code> 可以把 <code>CLAUDE.md</code> 之类的文件当作指令文件读取。</p><p>大小限制是硬性的：合并后受 <code>project_doc_max_bytes</code> 限制，默认 32 KiB，超出部分不再加入。这意味着你把指令写得再详细，超过阈值也不会生效。</p><p>这层的特点是<strong>完全可审计</strong>。它是文件，能被 git 记录，能 code review，能回滚。出问题时你能确切知道是哪一行规则导致的。</p><h2 id="二、第二层-memories-是异步编译出来的" tabindex="-1">二、第二层：Memories 是异步编译出来的 <a class="header-anchor" href="#二、第二层-memories-是异步编译出来的" aria-label="Permalink to “二、第二层：Memories 是异步编译出来的”">​</a></h2><p>第二层把记录拆成两段：单会话抽取，跨会话合并。两段可以分别指定模型，<code>extract_model</code> 负责前者，<code>consolidation_model</code> 负责后者。</p><p>产物是 Markdown 文件，下次会话只注入摘要层。</p><p>然后是整套门控设计，这是最值得看的部分：</p><table tabindex="0"><thead><tr><th>机制</th><th>行为</th></tr></thead><tbody><tr><td>默认状态</td><td>关闭，需要显式开启</td></tr><tr><td>会话筛选</td><td>跳过活跃或短命的会话</td></tr><tr><td>时间门控</td><td>会话结束不立即处理，默认空闲 6 小时后才进入候选</td></tr><tr><td>额度门控</td><td>剩余额度低于阈值时跳过后台生成，默认 25%</td></tr><tr><td>合并上限</td><td>参与合并的原始记忆默认 256 条，可调到 4096</td></tr><tr><td>时间剪枝</td><td>30 天未被使用的记忆不再参与合并</td></tr><tr><td>会话年龄</td><td>超过 30 天的会话不再参与生成</td></tr><tr><td>单次处理量</td><td>每次启动最多处理 16 条</td></tr><tr><td>隐私</td><td>生成字段做密钥脱敏；MCP 与联网会话可选择排除</td></tr></tbody></table><p><strong>读一遍这张表，你会发现没有一条在增加记忆。</strong></p><p>默认关闭、跳过短命会话、空闲才处理、额度不足就停、参与合并有上限、30 天剪枝、单次最多 16 条——每一条都在限制它记事。</p><p>这不是设计失误。它的目标很明确：<strong>省额度、防污染。</strong> 空闲门控避免总结尚未完成的工作，配额门控避免后台任务抢占前台额度，时间剪枝控制无限膨胀。</p><h2 id="三、召回机制没有公开" tabindex="-1">三、召回机制没有公开 <a class="header-anchor" href="#三、召回机制没有公开" aria-label="Permalink to “三、召回机制没有公开”">​</a></h2><p>这是最需要澄清的一点：官方文档只承诺&quot;把已有记忆注入未来会话&quot;，<strong>没有描述向量索引或相似度检索</strong>。</p><p>社区有说法称 Codex 对 <code>MEMORY.md</code> 做 grep，但那是二手推测，不是官方机制。把&quot;grep 记忆文件&quot;写成官方行为，是这类文章最常见的错误。</p><p>我在本机（2026-11-09）看过 <code>memories/</code> 目录，见到 <code>memory_summary.md</code>、<code>MEMORY.md</code>、<code>raw_memories.md</code>、<code>rollout_summaries/</code>、<code>extensions/ad_hoc/</code> 这些文件。但这是<strong>生成态</strong>，版本之间可能变化，不能当作官方契约。</p><h2 id="四、真正的结论" tabindex="-1">四、真正的结论 <a class="header-anchor" href="#四、真正的结论" aria-label="Permalink to “四、真正的结论”">​</a></h2><p><strong>第一层是人与模型之间的契约，第二层是模型与自己的对话。</strong></p><p>第一层你要认真写，因为它是唯一能精确控制行为的部分。它的失效方式是被 32 KiB 截断——所以规则要短、要靠近 cwd 生效。</p><p>第二层你不能精确控制，只能设边界：什么时候生成、什么时候不许生成、保留多久、合并多少。它的失效方式是过期信息污染——所以要有时间剪枝。</p><p>如果你的自建系统把这两件事混在一起，会同时失去两种保障：规则不再可审计，记忆不再可淘汰。</p><h2 id="不确定性与边界" tabindex="-1">不确定性与边界 <a class="header-anchor" href="#不确定性与边界" aria-label="Permalink to “不确定性与边界”">​</a></h2><ul><li>具体文件名与目录结构属生成态，v1/v2 迁移期间可能双写，升级后需重新核对。</li><li>&quot;摘要之外如何取细节&quot;官方未文档化；社区分析称对 <code>MEMORY.md</code> 执行 grep，属二手说法。</li><li>地区可用性、默认开关状态可能随版本调整。</li><li>本文以 2026-11-09 访问的 OpenAI 官方 Codex 文档为准。</li></ul><hr>',29)),c("p",null,[e[3]||(e[3]=t("总览见 ",-1)),o(d,{href:"/nebula-blog/vault/Knowledge/AI/三大编码 Agent 都没有记忆库.html"},{default:a(()=>[...e[0]||(e[0]=[t("三大编码 Agent 都没有记忆库",-1)])]),_:1}),e[4]||(e[4]=t("，对照见 ",-1)),o(d,{href:"/nebula-blog/vault/Knowledge/AI/Claude Code 的记忆系统.html"},{default:a(()=>[...e[1]||(e[1]=[t("Claude Code 的记忆系统",-1)])]),_:1}),e[5]||(e[5]=t("、",-1)),o(d,{href:"/nebula-blog/vault/Knowledge/AI/Cursor 的记忆系统.html"},{default:a(()=>[...e[2]||(e[2]=[t("Cursor 的记忆系统",-1)])]),_:1}),e[6]||(e[6]=t("。",-1))]),o(n),o(l)])}const v=s(g,[["render",u]]);export{N as __pageData,v as default};
